export interface CubieApiErrorPayload {
  success?: false;
  error?: string;
  message?: string;
  isVerified?: boolean;
}

export class CubieOAuthError extends Error {
  readonly status: number;
  readonly code: string;
  readonly payload: CubieApiErrorPayload;

  constructor(status: number, code: string, message: string, payload: CubieApiErrorPayload = {}) {
    super(message);
    this.name = 'CubieOAuthError';
    this.status = status;
    this.code = code;
    this.payload = payload;
  }
}

export class InvalidClientError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'invalid_client', 'Invalid public or secret credentials.', payload);
  }
}

export class InvalidRedirectUriError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'invalid_redirect_uri', 'redirect_uri is not registered for this application.', payload);
  }
}

export class InvalidGrantError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'invalid_grant', 'The authorization code is invalid, expired, or already used.', payload);
  }
}

export class InvalidTokenError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'invalid_token', 'The access token is invalid, expired, or belongs to another application.', payload);
  }
}

export class UserNotFoundError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'user_not_found', 'User not found.', payload);
  }
}

export class AccountInactiveError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'account_inactive', 'The account is inactive or in recovery.', payload);
  }
}

export class AccessRevokedError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'access_revoked', 'Authorization revoked.', payload);
  }
}

export class NotVerifiedError extends CubieOAuthError {
  readonly isVerified = false;

  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'not_verified', 'The account email is not verified.', payload);
  }
}

export class RateLimitedError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'rate_limited', payload.message || 'Too many requests. Please wait and try again.', payload);
  }
}

export class InternalError extends CubieOAuthError {
  constructor(status: number, payload: CubieApiErrorPayload) {
    super(status, 'internal_error', 'OAuth server internal error.', payload);
  }
}
