import { readResponse } from './http.js';
import type {
  AuthorizationCallback,
  CreateAuthorizationRequestOptions,
  CreateAuthorizationRequestResponse,
  ExchangeCodeOptions,
  TokenResponse,
  UserInfoResponse,
} from './types.js';

export const CUBIE_BASE_URL = 'https://cubie.com.br';

export interface CubieClientOptions {
  publicKey: string;
  secretKey: string;
  fetch?: typeof fetch;
}

export class CubieClient {
  readonly publicKey: string;
  readonly secretKey: string;
  private readonly fetchImpl: typeof fetch;

  constructor(options: CubieClientOptions) {
    if (!options.publicKey?.trim()) throw new TypeError('publicKey is required');
    if (!options.secretKey?.trim()) throw new TypeError('secretKey is required');
    this.publicKey = options.publicKey;
    this.secretKey = options.secretKey;
    this.fetchImpl = options.fetch || globalThis.fetch;

    if (!this.fetchImpl) {
      throw new Error('Native fetch is unavailable. Use Node.js 18 or provide options.fetch.');
    }
  }

  private async post<T>(path: string, body: Record<string, unknown>, headers: Record<string, string> = {}): Promise<T> {
    const response = await this.fetchImpl(`${CUBIE_BASE_URL}${path}`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Accept: 'application/json',
        ...headers,
      },
      body: JSON.stringify(body),
    });
    return readResponse<T>(response);
  }

  async createAuthorizationRequest(options: CreateAuthorizationRequestOptions): Promise<CreateAuthorizationRequestResponse> {
    if (!options.redirectUri?.trim()) throw new TypeError('redirectUri is required');

    const body: Record<string, unknown> = {
      public_key: this.publicKey,
      secret_key: this.secretKey,
      redirect_uri: options.redirectUri,
    };
    if (options.state !== undefined) body.state = options.state;

    return this.post<CreateAuthorizationRequestResponse>('/oauth/api/create-request', body);
  }

  async exchangeCode(options: ExchangeCodeOptions): Promise<TokenResponse> {
    if (!/^[a-f0-9]{64}$/.test(options.code || '')) throw new TypeError('code must contain 64 hexadecimal characters');
    if (!options.redirectUri?.trim()) throw new TypeError('redirectUri is required');

    return this.post<TokenResponse>('/oauth/api/token', {
      public_key: this.publicKey,
      secret_key: this.secretKey,
      code: options.code,
      redirect_uri: options.redirectUri,
    });
  }

  async getUserInfo(accessToken: string): Promise<UserInfoResponse> {
    if (!/^[a-f0-9]{64}$/i.test(accessToken || '')) throw new TypeError('accessToken must contain 64 hexadecimal characters');

    return this.post<UserInfoResponse>('/oauth/api/userinfo', {
      public_key: this.publicKey,
      secret_key: this.secretKey,
    }, {
      Authorization: `Bearer ${accessToken}`,
    });
  }

  parseAuthorizationCallback(urlOrSearch: string | URL): AuthorizationCallback {
    const url = typeof urlOrSearch === 'string'
      ? new URL(urlOrSearch.startsWith('http') ? urlOrSearch : `https://callback.local${urlOrSearch.startsWith('?') ? '' : '?'}${urlOrSearch}`)
      : urlOrSearch;

    const get = (key: string) => {
      const value = url.searchParams.get(key);
      return value === null ? undefined : value;
    };

    const result: AuthorizationCallback = {};
    const code = get('code');
    const state = get('state');
    const success = get('success');
    const error = get('error');
    const isVerified = get('isVerified');

    if (code !== undefined) result.code = code;
    if (state !== undefined) result.state = state;
    if (success === 'true' || success === 'false') result.success = success;
    if (error === 'access_denied') result.error = error;
    if (isVerified === 'true' || isVerified === 'false') result.isVerified = isVerified;
    return result;
  }
}
